package com.example.microservice.prototype;

import org.springframework.context.annotation.Scope;
import org.springframework.context.annotation.ScopedProxyMode;
import org.springframework.stereotype.Component;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import reactor.core.publisher.Mono;

@Component
@Scope(value = "prototype", proxyMode = ScopedProxyMode.TARGET_CLASS)
class TransientTransactionContext {
    private final long timestamp = System.currentTimeMillis();

    public long getTimestamp() {
        return timestamp;
    }
}

@RestController
public class PrototypeDemoController {

    private final TransientTransactionContext transactionContext;

    public PrototypeDemoController(TransientTransactionContext transactionContext) {
        this.transactionContext = transactionContext;
    }

    @GetMapping("/api/check-time")
    public Mono<Long> checkTime() {
        return Mono.just(transactionContext.getTimestamp());
    }
}
